const counterSlice = createSlice({
  name: 'counter',
  initialState: { value: 0 },
  reducers: {
    increment: (state) => { state.value += 1; }
  }
});

export const fetchUser = createAsyncThunk('user/fetch', async (id) => {
  const response = await api.getUser(id);
  return response.data;
});

const selectUsers = state => state.users.list;
const selectActiveFilter = state => state.users.filter;

export const selectActiveUsers = createSelector(
  [selectUsers, selectActiveFilter],
  (users, filter) => users.filter(user => user.status === filter)
);

export const api = createApi({
  reducerPath: 'pokemonApi',
  baseQuery: fetchBaseQuery({ baseUrl: '[https://pokeapi.co/api/v2/](https://www.google.com/search?q=https://pokeapi.co/api/v2/)' }),
  endpoints: (builder) => ({
    getPokemon: builder.query({ query: (name) => `pokemon/${name}` })
  })
});
